INSERT INTO `products` VALUES (1,'Camera Canon PowerShot G7 X Mark III','CAM-CANON-001','camera-canon-powershot-g7-x-mark-iii','Appareil photo compact haut de gamme idéal pour le vlogging et la photographie de qualité.\n\nSpécifications techniques :\n• Capteur : CMOS empilé de 1 pouce, 20,1 MP\n• Objectif : Canon 8,8-36,8 mm f/1,8-2,8 (équivalent 24-100 mm)\n• Vidéo : 4K UHD à 30 ips, Full HD à 120 ips\n• Stabilisation : Stabilisation optique de l\'image (IS)\n• Écran : Écran tactile inclinable de 3,0 pouces\n• Connectivité : Wi-Fi, Bluetooth, USB-C, Micro HDMI\n• Poids : Environ 304 g (avec batterie et carte)',0.00,NULL,NULL,0,2,1,0.00,0,2,NULL,1,'images/camera/cat_cameras.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-23 15:44:03'),(2,'Caméra cinéma plein format Sony FX3A','CAM-SONY-002','camera-cinema-plein-format-sony-fx3a','Caméra cinéma plein format offrant des performances exceptionnelles en faible luminosité et en vidéo 4K.\n\nSpécifications techniques :\n• Capteur : Plein format Exmor R CMOS, 12,1 MP\n• Monture : Sony E\n• Vidéo : 4K 120p, Full HD 240p, 10-bit 4:2:2\n• Sensibilité : ISO 80-102 400 (étendu jusqu\'à 409 600)\n• Stabilisation : Stabilisation sur 5 axes (jusqu\'à 5,5 stops)\n• Écran : Écran tactile LCD inclinable de 3,0 pouces\n• Poids : Environ 715 g (boîtier uniquement)',45980.00,39990.00,NULL,10,2,1,32392.00,10,2,NULL,1,'images/camera/prod_blackmagic_cine.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(3,'Caméra cinéma Sony FX5','CAM-SONY-003','camera-cinema-sony-fx5','Caméra cinéma professionnelle conçue pour la production vidéo et cinématographique haut de gamme.\n\nSpécifications techniques :\n• Capteur : Plein format Exmor R CMOS, 24,2 MP\n• Monture : Sony E\n• Vidéo : 4K 60p, 8K 30p, 10-bit 4:2:2, S-Cinetone\n• Sensibilité : ISO 80-25 600 (dual native ISO)\n• Stabilisation : Stabilisation active sur 5 axes\n• Écran : Écran tactile LCD articulé de 3,2 pouces\n• Poids : Environ 850 g (boîtier uniquement)',0.00,NULL,NULL,10,2,1,0.00,10,2,NULL,1,'images/camera/prod_blackmagic_cine.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-23 15:44:03'),(4,'Caméra d\'action 360° Insta360 Ace Pro 2','CAM-INSTA-004','camera-daction-360-insta360-ace-pro-2','Caméra d\'action 360° avancée avec fonctionnalités IA et vidéo haute résolution.\n\nSpécifications techniques :\n• Capteur : Capteur CMOS de 1 pouce co-développé avec Leica, 50 MP\n• Vidéo : 8K 30fps, 4K 120fps, HDR vidéo\n• Stabilisation : FlowState 3.0 avec Horizon Lock\n• Écran : Double écran tactile (avant 2,4 et arrière 2,5 pouces)\n• Étanchéité : Étanche jusqu\'à 10 mètres sans boîtier\n• Poids : Environ 177 g',6500.00,4990.00,NULL,10,2,1,3992.00,10,2,NULL,1,'images/camera/cat_drones.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(5,'Caméra Insta360 X6 Standard','CAM-INSTA-005','camera-insta360-x6-standard','Bundle standard de la dernière caméra 360° avec des capacités de résolution 8K.\n\nSpécifications techniques :\n• Capteur : Double capteur 1/1,28 pouce, 48 MP au total\n• Vidéo : 8K 30fps en 360°, 4K 60fps en mode objectif unique\n• Stabilisation : FlowState avec verrouillage de l\'horizon à 360°\n• Étanchéité : Étanche jusqu\'à 15 mètres\n• Fonctionnalités : Perche à selfie invisible, remplacement des objectifs\n• Poids : Environ 205 g',8249.00,NULL,NULL,10,2,1,6599.20,10,2,NULL,1,'images/camera/cat_drones.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-23 15:44:03'),(6,'Camera instantané FUJIFILM instax mini 12','CAM-FUJI-006','camera-instantane-fujifilm-instax-mini-12','Appareil photo instantané analogique amusant et facile à utiliser, disponible en plusieurs couleurs.\n\nSpécifications techniques :\n• Type : Appareil photo instantané analogique\n• Objectif : 60 mm, f/12,7\n• Flash : Flash automatique avec mode selfie\n• Format de film : Fujifilm Instax Mini\n• Alimentation : 2 piles AA\n• Poids : Environ 306 g (sans les piles)',1300.00,1090.00,NULL,10,2,1,872.00,10,2,NULL,1,'images/camera/cat_cameras.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(7,'Camera Sony A7 V (ILCE-7M5)','CAM-SONY-007','camera-sony-a7-v-ilce-7m5','Caméra hybride plein format de nouvelle génération avec autofocus IA avancé.\n\nSpécifications techniques :\n• Capteur : Plein format Exmor R CMOS, 33 MP\n• Monture : Sony E\n• Vidéo : 4K 60p (suréchantillonné 7K), 10-bit 4:2:2\n• Autofocus : AF hybride rapide avec IA (reconnaissance humaine, animale, végétale)\n• Stabilisation : Stabilisation sur 5 axes (jusqu\'à 8 stops)\n• Écran : Écran tactile LCD entièrement articulé de 3,2 pouces\n• Poids : Environ 660 g (avec batterie et carte)',36890.00,34490.00,NULL,10,2,1,22312.00,10,2,NULL,1,'images/camera/prod_sony_a7iv.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(8,'Camera Sony Alpha 6600','CAM-SONY-008','camera-sony-alpha-6600','Caméra hybride APS-C haut de gamme avec une excellente autonomie et un autofocus rapide.\n\nSpécifications techniques :\n• Capteur : APS-C Exmor CMOS, 24,2 MP\n• Monture : Sony E\n• Vidéo : 4K 30p, Full HD 120p\n• Autofocus : AF hybride rapide avec suivi en temps réel et Eye AF\n• Stabilisation : Stabilisation sur 5 axes\n• Batterie : NP-FZ100 (grande autonomie)\n• Poids : Environ 503 g (avec batterie et carte)',12900.00,11500.00,NULL,0,2,1,9200.00,0,2,NULL,1,'images/camera/prod_sony_a7iv.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(9,'Camera Sony Alpha 7 II','CAM-SONY-009','camera-sony-alpha-7-ii','Caméra hybride plein format fiable avec stabilisation sur 5 axes.\n\nSpécifications techniques :\n• Capteur : Plein format Exmor CMOS, 24,3 MP\n• Monture : Sony E\n• Vidéo : Full HD 1080p à 60 ips\n• Stabilisation : Stabilisation sur 5 axes (premier plein format à l\'avoir)\n• Écran : Écran LCD inclinable de 3,0 pouces\n• Poids : Environ 599 g (avec batterie et carte)',11900.00,7900.00,NULL,0,2,1,6320.00,0,2,NULL,1,'images/camera/prod_sony_a7iv.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(10,'Caméscope professionnel Canon XA60B UHD 4K','CAM-CANON-010','camescope-professionnel-canon-xa60b-uhd-4k','Caméscope professionnel 4K UHD idéal pour la diffusion et la vidéo d\'entreprise.\n\nSpécifications techniques :\n• Capteur : CMOS 1/2,3 pouce, 3 capteurs (système 3-CMOS)\n• Objectif : Zoom optique 20x (26,8-576 mm équivalent)\n• Vidéo : 4K UHD 50p/60p, Full HD 120p\n• Stabilisation : Stabilisation optique avancée à 5 axes\n• Connectivité : Wi-Fi, USB-C, 2x entrées XLR audio\n• Poids : Environ 1,3 kg',14490.00,12990.00,NULL,10,2,1,10392.00,10,2,NULL,1,'images/camera/prod_blackmagic_cine.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(11,'Canon EOS 2000D + Objectif EF-S 18-55mm IS II','CAM-CANON-011','canon-eos-2000d-objectif-ef-s-18-55mm-is-ii','Kit DSLR d\'entrée de gamme parfait pour les débutants en photographie.\n\nSpécifications techniques :\n• Capteur : APS-C CMOS, 24,1 MP\n• Monture : Canon EF/EF-S\n• Vidéo : Full HD 1080p à 30 ips\n• Autofocus : AF à 9 points (1 point croisé)\n• Écran : Écran LCD fixe de 3,0 pouces\n• Connectivité : Wi-Fi, NFC\n• Poids : Environ 475 g (boîtier uniquement)',5590.00,4990.00,NULL,10,2,1,3992.00,10,2,NULL,1,'images/camera/cat_cameras.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(12,'Canon EOS 250D Camera + Objectif EF-S 18-55mm IS STM','CAM-CANON-012','canon-eos-250d-camera-objectif-ef-s-18-55mm-is-stm','DSLR compact et léger avec vidéo 4K et écran tactile articulé.\n\nSpécifications techniques :\n• Capteur : APS-C CMOS, 24,1 MP\n• Monture : Canon EF/EF-S\n• Vidéo : 4K UHD 25p, Full HD 60p\n• Autofocus : AF Dual Pixel CMOS sur l\'écran\n• Écran : Écran tactile LCD entièrement articulé de 3,0 pouces\n• Poids : Environ 450 g (boîtier uniquement)',7490.00,6890.00,NULL,0,2,1,5512.00,0,2,NULL,1,'images/camera/cat_cameras.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(13,'Canon EOS R3 Mirrorless Camera','CAM-CANON-013','canon-eos-r3-mirrorless-camera','Caméra hybride plein format phare conçue pour le sport professionnel et la faune.\n\nSpécifications techniques :\n• Capteur : Plein format CMOS empilé rétro-éclairé, 24,1 MP\n• Monture : Canon RF\n• Vidéo : 6K 60p RAW, 4K 120p\n• Autofocus : AF à détection de l\'œil, du visage, de la tête et du corps avec IA\n• Stabilisation : Stabilisation sur 5 axes (jusqu\'à 8 stops)\n• Poids : Environ 1015 g (avec batterie et carte)',51000.00,NULL,NULL,0,2,1,40800.00,0,2,NULL,1,'images/camera/cat_cameras.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-23 15:44:03'),(14,'Canon EOS R6 Mark II Mirrorless Camera','CAM-CANON-014','canon-eos-r6-mark-ii-mirrorless-camera','Caméra hybride plein format polyvalente avec prise de vue en continu à haute vitesse.\n\nSpécifications techniques :\n• Capteur : Plein format CMOS, 24,2 MP\n• Monture : Canon RF\n• Vidéo : 4K 60p (suréchantillonné), Full HD 180p\n• Autofocus : AF Dual Pixel CMOS II avec suivi intelligent des sujets\n• Stabilisation : Stabilisation sur 5 axes (jusqu\'à 8 stops)\n• Poids : Environ 670 g (avec batterie et carte)',27900.00,20890.00,NULL,0,2,1,16712.00,0,2,NULL,1,'images/camera/cat_cameras.jpg',NULL,NULL,'unknown','active','2026-10-23 15:44:03','2026-10-24 15:04:49'),(15,'DJI Osmo 360 Action Camera Adventure Combo','CAM-DJI-015','dji-osmo-360-action-camera-adventure-combo','Kit de caméra d\'action 360° robuste avec accessoires de montage pour l\'aventure.\n\nSpécifications techniques :\n• Capteur : Capteur 360° de 1 pouce\n• Vidéo : 8K 360° natif, 4K 120fps en mode objectif unique (170°)\n• Stabilisation : Stabilisation électronique avancée (Horizon Steady)\n• Stockage : 128 Go intégrés\n• Étanchéité : Conception robuste résistante aux intempéries\n• Poids : Environ 220 g',7900.00,6690.00,NULL,10,2,1,5352.00,10,2,NULL,1,'images/camera/cat_drones.jpg',NULL,NULL,'unknow